sksl:
uniform shader image;
uniform shader bright;
uniform float2 size;
uniform float time;
uniform float threshold;
uniform float blur;
uniform float streakLength;
uniform float angle;
uniform float falloff;
uniform float intensity;
layout(color) uniform half4 tint;
uniform float tintAmount;
uniform float blend;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
float luma(float3 c) {
    return dot(c, float3(0.2126, 0.7152, 0.0722));
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float3 blendm(float3 b, float3 s, float m) {
    if (m < 0.5) return s;
    if (m < 1.5) return b + s;
    if (m < 2.5) return 1.0 - (1.0 - b) * (1.0 - s);
    if (m < 3.5) return b * s;
    if (m < 4.5) return mix(2.0 * b * s, 1.0 - 2.0 * (1.0 - b) * (1.0 - s), step(float3(0.5), b));
    if (m < 5.5) return (1.0 - 2.0 * s) * b * b + 2.0 * s * b;
    if (m < 6.5) return max(b, s);
    if (m < 7.5) return min(b, s);
    if (m < 8.5) return abs(b - s);
    return b / max(1.0 - s, 0.001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float2 dir = float2(cos(radians(angle)), sin(radians(angle)));
    float4 acc = float4(0.0);
    float ws = 0.0;
    for (int i = 0; i < 17; i++) {
        float t = float(i) / 8.0 - 1.0;
        float w = exp(-pow(abs(t), falloff) * 3.0);
        acc += float4(bright.eval(clamp(coord + dir * t * streakLength * 0.5, float2(0.0), size))) * w;
        ws += w;
    }
    float3 g = unp(acc / ws) * (acc.a / ws);
    g = mix(g, g * float3(tint.rgb) * 1.6, tintAmount) * intensity;
    float3 o = mix(s, blendm(s, g, blend), saturate(luma(g) * 4.0));
    return fin(c, float4(max(o, float3(0.0)) * max(c.a, saturate(acc.a / ws * intensity)), max(c.a, saturate(acc.a / ws * intensity))), opacity);
}
